<script lang="ts">
  import GraphPanel from './GraphPanel.svelte';import FilePanel from './FilePanel.svelte';import TerminalPanel from './TerminalPanel.svelte';import DatabasePanel from './DatabasePanel.svelte';import OutputPanel from './OutputPanel.svelte';import DetailsPanel from './DetailsPanel.svelte';import MetricsPanel from './MetricsPanel.svelte';import Navigator from './Navigator.svelte';import FilesystemTree from './FilesystemTree.svelte';
